// Linked browser-demo production model and batch-scoped report exports.
const PLANTKEY='power-mes-plant-v1';let plant={lines:[{id:'L-A01',code:'A01',name:'A01 装配线'},{id:'L-A02',code:'A02',name:'A02 装配线'},{id:'L-A03',code:'A03',name:'A03 测试线'},{id:'L-B01',code:'B01',name:'B01 包装线'}],stations:steps.map((s,i)=>({id:'A01-0'+(i+1),lineId:'L-A01',process:i,name:s})),orderMeta:{}};
try{let saved=JSON.parse(localStorage.getItem(PLANTKEY)||'null');if(saved&&Array.isArray(saved.lines)&&Array.isArray(saved.stations)&&saved.orderMeta)plant=saved}catch{}
for(let o of orders)if(!plant.orderMeta[o[0]]){let line=plant.lines.find(l=>l.name===o[3])||plant.lines[0];plant.orderMeta[o[0]]={lineId:line?.id||'',batch:'B-'+o[0].replace(/^MO-/,'')}}
let activeStationKey='';try{activeStationKey=sessionStorage.getItem('mes-station-id')||''}catch{}let reportExport=null;
function savePlant(){localStorage.setItem(PLANTKEY,JSON.stringify(plant))}savePlant();
function wfCurrentStation(){let s=plant.stations.find(s=>s.id===activeStationKey&&s.process===wfStage);return s||plant.stations.find(s=>s.process===wfStage&&s.lineId===(plant.orderMeta[wfJob.id]?.lineId||'L-A01'))||null}
function wfCurrentLine(){let s=wfCurrentStation();return plant.lines.find(l=>l.id===(s?.lineId||plant.orderMeta[wfJob.id]?.lineId))||null}
function wfCurrentBatch(){return plant.orderMeta[wfJob.id]?.batch||'未分批'}
stationId=function(){return wfCurrentStation()?.id||'未配置工位'};
function selectProductionOrder(id){let o=orders.find(o=>o[0]===id);if(!o)return;wfJob.id=o[0];wfJob.product=o[1];wfJob.spec=o[2];wfJob.plan=Number(String(o[4]).replaceAll(',',''))||0;wfCode='';autoPending=false;wfChecked=false}
function canPlantEdit(){if(!auth||!['admin','supervisor'].includes(auth.role)){toast('当前角色无产线管理权限');return false}return true}
renderers.stations=function(){return heading('产线与工位','产线 → 工位 → 工序 → 工单批次 → 生产记录，保持完整关联',button('＋ 新建产线',"plantLineForm()",'primary')+button('＋ 新建工位',"plantStationForm()"))+`<div class="notice">工位必须归属产线并关联工序。已有工单、设备或生产历史引用的数据不能直接删除。</div>`+plant.lines.map(line=>panel(escapeHtml(line.name),`<div class="machinegrid">${plant.stations.filter(s=>s.lineId===line.id).map(s=>`<div class="machine"><div class="panelhead"><b>${escapeHtml(s.id)}</b>${badge(steps[s.process])}</div><h2>${escapeHtml(s.name)}</h2><p class="sub">所属产线 ${escapeHtml(line.code)} · ${s.process===2?'仪器结果自动上传':'扫码 / SOP / 消息'}</p><div class="actions">${button('进入工位',`openLinkedStation('${s.id}')`)}${button('删除',`deletePlantStation('${s.id}')`,'danger')}</div></div>`).join('')||'<p class="sub">尚未配置工位，请添加并关联工序。</p>'}</div>`,button('删除产线',`deletePlantLine('${line.id}')`,'danger'))).join('')};
function plantLineForm(){if(!canPlantEdit())return;modal('新建产线',`<div class="formgrid"><label class="field">产线编码<input id="newLineCode" placeholder="例如 C01"></label><label class="field">产线名称<input id="newLineName" placeholder="例如 C01 装配线"></label></div>`,button('保存',"savePlantLine()",'primary'))}
function savePlantLine(){if(!canPlantEdit())return;let code=$('#newLineCode').value.trim().toUpperCase(),name=$('#newLineName').value.trim();if(!/^[A-Z0-9-]{1,20}$/.test(code)||!name||/[<>]/.test(name)){toast('请填写有效编码与名称');return}if(plant.lines.some(l=>l.code===code||l.name===name)){toast('产线编码或名称重复');return}plant.lines.push({id:'L-'+crypto.randomUUID(),code,name});savePlant();adminLog('新增产线',name);closeModal();render()}
function plantStationForm(){if(!canPlantEdit())return;if(!plant.lines.length){toast('请先新建产线');return}modal('新建工位',`<div class="formgrid"><label class="field">工位编码<input id="newStationCode" placeholder="例如 C01-01"></label><label class="field">工位名称<input id="newStationName" placeholder="例如 电芯绑定工位"></label><label class="field">所属产线<select id="newStationLine">${plant.lines.map(l=>`<option value="${l.id}">${escapeHtml(l.name)}</option>`).join('')}</select></label><label class="field">关联工序<select id="newStationProcess">${steps.map((s,i)=>`<option value="${i}">${s}</option>`).join('')}</select></label></div>`,button('保存',"savePlantStation()",'primary'))}
function savePlantStation(){if(!canPlantEdit())return;let id=$('#newStationCode').value.trim().toUpperCase(),name=$('#newStationName').value.trim(),lineId=$('#newStationLine').value,process=Number($('#newStationProcess').value);if(!/^[A-Z0-9-]{1,30}$/.test(id)||!name||!plant.lines.some(l=>l.id===lineId)||!Number.isInteger(process)||process<0||process>4){toast('请填写有效工位，并关联产线和工序');return}if(plant.stations.some(s=>s.id===id)){toast('工位编码重复');return}plant.stations.push({id,name,lineId,process});savePlant();adminLog('新增工位',id+' / '+name);closeModal();render()}
function lineReferenced(id){return Object.values(plant.orderMeta).some(m=>m.lineId===id)||units.some(u=>u.lineId===id)||scanLogs.some(x=>plant.stations.some(s=>s.lineId===id&&s.id===x.station))}
function deletePlantLine(id){if(!canPlantEdit())return;let line=plant.lines.find(l=>l.id===id);if(!line)return;if(plant.stations.some(s=>s.lineId===id)||lineReferenced(id)){toast('产线已关联工位、工单或生产记录，不能删除');return}modal('删除产线',`<p>确认删除未被引用的产线“${escapeHtml(line.name)}”？</p>`,button('取消','closeModal()')+button('确认删除',`confirmPlantLineDelete('${id}')`,'danger'))}
function confirmPlantLineDelete(id){if(!canPlantEdit()||plant.stations.some(s=>s.lineId===id)||lineReferenced(id))return;plant.lines=plant.lines.filter(l=>l.id!==id);savePlant();adminLog('删除产线',id);closeModal();render()}
function stationReferenced(id){return scanLogs.some(x=>x.station===id)||units.some(u=>u.history.some(h=>h.station===id||h.note?.includes(id)))||id==='A01-03'}
function deletePlantStation(id){if(!canPlantEdit())return;if(stationReferenced(id)){toast('工位已有生产历史或设备绑定，不能删除');return}modal('删除工位',`<p>确认删除未被生产记录引用的工位“${escapeHtml(id)}”？</p>`,button('取消','closeModal()')+button('确认删除',`confirmPlantStationDelete('${id}')`,'danger'))}
function confirmPlantStationDelete(id){if(!canPlantEdit()||stationReferenced(id))return;plant.stations=plant.stations.filter(s=>s.id!==id);if(activeStationKey===id){activeStationKey='';wfCode='';autoPending=false;sessionStorage.removeItem('mes-station-id')}savePlant();adminLog('删除工位',id);closeModal();render()}
function openLinkedStation(id){let s=plant.stations.find(s=>s.id===id);if(!s)return;let job=orders.find(o=>plant.orderMeta[o[0]]?.lineId===s.lineId);if(!job){toast('请先为该产线创建工单及批次');return}activeStationKey=id;wfStage=s.process;selectProductionOrder(job[0]);sessionStorage.setItem('mes-station-id',id);wfTab='work';setMode('station')}
wfChooseStation=function(){modal('切换工位与生产工单',`<label class="field">工位<select id="linkedStation" onchange="linkedJobChoices()">${plant.stations.map(s=>`<option value="${s.id}" ${s.id===stationId()?'selected':''}>${escapeHtml(plant.lines.find(l=>l.id===s.lineId)?.name||'')} / ${escapeHtml(s.id)} / ${steps[s.process]}</option>`).join('')}</select></label><label class="field" style="margin-top:16px">该产线工单 / 批次<select id="linkedOrder"></select></label>`,button('取消','closeModal()')+button('确认切换',"switchLinkedStation()",'primary'));linkedJobChoices()};
function linkedJobChoices(){let s=plant.stations.find(s=>s.id===$('#linkedStation').value);$('#linkedOrder').innerHTML=orders.filter(o=>plant.orderMeta[o[0]]?.lineId===s?.lineId).map(o=>`<option value="${escapeHtml(o[0])}" ${o[0]===wfJob.id?'selected':''}>${escapeHtml(o[0])} / ${escapeHtml(plant.orderMeta[o[0]].batch)}</option>`).join('')}
function switchLinkedStation(){let s=plant.stations.find(s=>s.id===$('#linkedStation').value),o=orders.find(o=>o[0]===$('#linkedOrder').value);if(!s||!o||plant.orderMeta[o[0]]?.lineId!==s.lineId){toast('请选择与工位所属产线一致的工单');return}activeStationKey=s.id;wfStage=s.process;selectProductionOrder(o[0]);sessionStorage.setItem('mes-station-id',s.id);sessionStorage.setItem('mes-workstation',String(wfStage));wfTab='work';autoStage=wfStage;barcodeError='';closeModal();render()}
const beforeLinkedNewRecord=newRecord;newRecord=function(kind){if(kind!=='生产工单')return beforeLinkedNewRecord(kind);if(!canPlantEdit())return;modal('新建生产工单',`<div class="formgrid"><label class="field">工单编号<input id="jobId" placeholder="例如 MO-20261016-005"></label><label class="field">生产批次<input id="jobBatch" placeholder="例如 B-20261016-A"></label><label class="field">产品名称<input id="jobProduct" placeholder="例如 P20 20W 快充"></label><label class="field">计划数量<input id="jobPlan" type="number" min="1"></label><label class="field">关联产线<select id="jobLine">${plant.lines.map(l=>`<option value="${l.id}">${escapeHtml(l.name)}</option>`).join('')}</select></label><label class="field">计划完成<input id="jobDue" type="date"></label></div>`,button('保存工单',"saveLinkedJob()",'primary'))};
function saveLinkedJob(){if(!canPlantEdit())return;let id=$('#jobId').value.trim(),batch=$('#jobBatch').value.trim(),product=$('#jobProduct').value.trim(),plan=Number($('#jobPlan').value),line=plant.lines.find(l=>l.id===$('#jobLine').value),due=$('#jobDue').value;if(!id||!batch||!product||/[<>]/.test(id+batch+product)||!Number.isInteger(plan)||plan<1||!line||!due){toast('请完整填写有效工单、批次、数量和产线');return}if(orders.some(o=>o[0]===id)){toast('工单编号重复');return}orders.unshift([id,product,'标准规格',line.name,String(plan),'0',0,'待开工',due]);plant.orderMeta[id]={lineId:line.id,batch};savePlant();persistAdmin();adminLog('新增生产工单',id+' / '+batch+' / '+line.name);closeModal();render()}
const linkedLookupBase=wfLookup;wfLookup=function(){let c=$('#wfScan').value.trim(),u=units.find(x=>x.main===c||x.sn===c),s=wfCurrentStation();if(!s){toast('当前工位未配置，请先选择有效工位');return}if(u&&((u.order||'MO-20261015-001')!==wfJob.id||(u.lineId&&u.lineId!==s.lineId))){barcodeError='该产品不属于当前工单或产线，禁止流转';wfLog('工单关联校验',c,u.main,'拦截',barcodeError);toast(barcodeError);return}linkedLookupBase();let found=units.find(x=>x.main===c);if(wfStage===0&&found&&!found.lineId){found.order=wfJob.id;found.lineId=s.lineId;found.batch=wfCurrentBatch();keep()}};
const linkedEventBase=wfEvent;wfEvent=function(u,title,note){linkedEventBase(u,title,note);Object.assign(u.history.at(-1),{station:stationId(),lineId:wfCurrentLine()?.id||'',process:wfStage,user:wfUser.id,order:wfJob.id,batch:wfCurrentBatch()})};
const linkedSummaryBase=wfOrderSummary;wfOrderSummary=function(){let html=linkedSummaryBase();return html.replace('A01 产线',escapeHtml(wfCurrentLine()?.name||'未选择产线')+' / 批次 '+escapeHtml(wfCurrentBatch()))};
const linkedStationBase=station;station=function(){let html=linkedStationBase();if(mesServer&&!serverEdit){let s=wfCurrentStation();if(s)html=html.replace(/A01-03 · 仪器测试/g,escapeHtml(s.id)+' · 仪器测试')}return html};
names.reports='生产报表';navs.forEach(g=>g[1].forEach(n=>{if(n[0]==='reports')n[2]='生产报表'}));
function reportBatchOf(u){return u.batch||plant.orderMeta[u.order||'MO-20261015-001']?.batch||'未分批'}
function reportSelection(){return {order:$('#reportOrder')?.value||'',batch:$('#reportBatch')?.value||'',query:($('#reportQuery')?.value||'').trim().toLowerCase(),result:$('#reportResult')?.value||''}}
function selectedReportUnits(sel){return units.filter(u=>{let order=u.order||'MO-20261015-001';return (!sel.order||order===sel.order)&&(!sel.batch||reportBatchOf(u)===sel.batch)&&(!sel.query||[u.main,u.cell,u.sn,u.pack].some(c=>(c||'').toLowerCase().includes(sel.query)))&&(!sel.result||(u.tests.at(-1)?.result||'未测试')===sel.result)})}
renderers.reports=function(){return heading('生产报表','按工单与批次检索产品、绑定、过站和全部测试记录')+`<div class="notice">导出必须选择具体工单和批次；导出范围同时遵循条码搜索与结果筛选，不支持一键全量导出。</div>`+panel('查询条件',`<div class="filters"><select id="reportOrder" onchange="reportBatchChoices();refreshProductionReport()"><option value="">全部工单（仅查询）</option>${orders.map(o=>`<option value="${escapeHtml(o[0])}">${escapeHtml(o[0])}</option>`).join('')}</select><select id="reportBatch" onchange="refreshProductionReport()"><option value="">选择批次</option></select><input id="reportQuery" placeholder="搜索主码、电芯码、SN、包装码" oninput="refreshProductionReport()"><select id="reportResult" onchange="refreshProductionReport()"><option value="">全部测试结果</option><option>PASS</option><option>FAIL</option><option>未测试</option></select></div><div class="actions">${button('导出产品生产明细',"prepareBatchExport('products')")}${button('导出测试明细',"prepareBatchExport('tests')")}${button('导出过站明细',"prepareBatchExport('history')")}</div><p class="hint">CSV 可用 Excel 打开；测试明细保留每一次 PASS / FAIL 和复测，生产数量按产品去重。</p>`)+`<div id="productionReport">${productionReportBody(selectedReportUnits({}))}</div>`};
function reportBatchChoices(){let order=$('#reportOrder').value;let batches=[...new Set([...units.filter(u=>!order||(u.order||'MO-20261015-001')===order).map(reportBatchOf),...(order?[plant.orderMeta[order]?.batch]:Object.values(plant.orderMeta).map(m=>m.batch))].filter(Boolean))];$('#reportBatch').innerHTML='<option value="">选择批次</option>'+batches.map(b=>`<option value="${escapeHtml(b)}">${escapeHtml(b)}</option>`).join('')}
function refreshProductionReport(){$('#productionReport').innerHTML=productionReportBody(selectedReportUnits(reportSelection()))}
function productionReportBody(list){return stats([['产品数量',String(list.length),'按主码去重'],['测试次数',String(list.reduce((a,u)=>a+u.tests.length,0)),'包括所有复测'],['最新测试合格',String(list.filter(u=>lastPass(u)).length),'按每台最新结果'],['完成包装',String(list.filter(u=>u.pack).length),'已绑定包装码']])+panel('生产明细',table(['工单 / 批次','主码','电芯码','SN','包装码','测试次数 / 最新结果','操作'],list.length?list.map(u=>[escapeHtml(u.order||'MO-20261015-001')+'<small>'+escapeHtml(reportBatchOf(u))+'</small>',escapeHtml(u.main),escapeHtml(u.cell)||'—',escapeHtml(u.sn)||'—',escapeHtml(u.pack)||'—',u.tests.length+' / '+badge(u.tests.at(-1)?.result||'未测试'),`<button class="link" onclick="productionDetail('${encodeURIComponent(u.main).replaceAll("'",'%27')}')">完整履历</button>`]):[['—','—','—','—','—','暂无匹配数据','—']]))}
function productionDetail(encoded){let u=units.find(x=>x.main===decodeURIComponent(encoded));if(!u)return;modal('生产完整明细',detailRows([['工单',escapeHtml(u.order||'MO-20261015-001')],['批次',escapeHtml(reportBatchOf(u))],['主码',escapeHtml(u.main)],['电芯码',escapeHtml(u.cell)],['SN',escapeHtml(u.sn)],['包装码',escapeHtml(u.pack)]])+table(['时间','结果','电压','电流','记录编号'],u.tests.map(t=>[escapeHtml(t.time),badge(t.result),t.voltage+' V',t.current+' A',escapeHtml(t.record)]))+wfHistory(u))}
function reportCsvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function buildBatchExport(kind,selection){if(!selection.order||!selection.batch)throw Error('请选择具体工单和批次后再导出');let list=selectedReportUnits(selection);if(!list.length)throw Error('当前批次和筛选条件下没有生产记录');let common=u=>[u.order||'MO-20261015-001',reportBatchOf(u),plant.lines.find(l=>l.id===(u.lineId||plant.orderMeta[u.order||'MO-20261015-001']?.lineId))?.name||'',u.main,u.cell,u.sn,u.pack];let head=['工单','批次','产线','主码','电芯码','SN','包装码'],rows=[];if(kind==='products'){head.push('测试次数','最新测试结果','过站履历');rows=list.map(u=>[...common(u),u.tests.length,u.tests.at(-1)?.result||'未测试',u.history.map(h=>h.time+' '+h.title+' '+h.note).join(' | ')])}else if(kind==='tests'){head.push('测试记录编号','时间','设备','结果','电压(V)','电流(A)','测试程序版本','完整测试数据JSON','原始记录引用');rows=list.flatMap(u=>u.tests.map(t=>[...common(u),t.record,t.time,t.device||'未记录',t.result,t.voltage,t.current,t.program_version||'未记录',JSON.stringify(t),t.raw_log||t.raw_file||'未记录']))}else if(kind==='history'){head.push('时间','工序','工位','操作人','记录内容');rows=list.flatMap(u=>u.history.map(h=>[...common(u),h.time,h.title,h.station||'未记录',h.user||'未记录',h.note]))}else throw Error('无效导出类型');if(!rows.length)throw Error('当前筛选没有此类明细记录');return {selection:{...selection},units:list.length,rows:rows.length,kind,csv:'\ufeff'+[head,...rows].map(r=>r.map(reportCsvCell).join(',')).join('\r\n')}}
function prepareBatchExport(kind){try{reportExport=buildBatchExport(kind,reportSelection());modal('确认按批次导出',detailRows([['工单',escapeHtml(reportExport.selection.order)],['批次',escapeHtml(reportExport.selection.batch)],['条码搜索',escapeHtml(reportExport.selection.query)||'不限'],['测试结果筛选',escapeHtml(reportExport.selection.result)||'不限'],['产品数量',reportExport.units+' 台'],['导出明细',reportExport.rows+' 行']]),button('取消','closeModal()')+button('下载所选批次 CSV',"downloadBatchExport()",'primary'))}catch(e){toast(e.message)}}
function downloadBatchExport(){if(!reportExport)return;let e=reportExport;let name=('MES-'+e.selection.order+'-'+e.selection.batch+'-'+e.kind).replace(/[^A-Za-z0-9_\-]/g,'_')+'.csv';let url=URL.createObjectURL(new Blob([e.csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);adminLog('按批次导出',e.selection.order+' / '+e.selection.batch+' / '+e.rows+' 行');reportExport=null;closeModal();toast('已触发所选批次明细下载')}
const renderBeforeLinkedOps=render;render=function(){renderBeforeLinkedOps();if(auth&&mode==='pc'&&page==='reports')reportBatchChoices()};
render();

const backupBeforeRelations=backupData;backupData=function(){let d=backupBeforeRelations();d.productionModel=JSON.parse(JSON.stringify(plant));d.sopMetadata=JSON.parse(JSON.stringify(sopGroups));return d};
function validateProductionModel(m,d){if(!m||!Array.isArray(m.lines)||!Array.isArray(m.stations)||!m.orderMeta)throw Error('产线工位配置不完整');let lineIds=new Set(),lineCodes=new Set(),stationIds=new Set();for(let l of m.lines){if(!l||typeof l.id!=='string'||typeof l.code!=='string'||typeof l.name!=='string'||lineIds.has(l.id)||lineCodes.has(l.code))throw Error('产线配置无效或重复');lineIds.add(l.id);lineCodes.add(l.code)}for(let s of m.stations){if(!s||typeof s.id!=='string'||typeof s.name!=='string'||!lineIds.has(s.lineId)||stationIds.has(s.id)||!Number.isInteger(s.process)||s.process<0||s.process>4)throw Error('工位缺少有效产线或工序');stationIds.add(s.id)}for(let o of d.orders){let meta=m.orderMeta[o[0]];if(!meta||!lineIds.has(meta.lineId)||typeof meta.batch!=='string'||!meta.batch)throw Error('工单缺少有效产线或批次')}for(let u of d.units){if(u.lineId&&!lineIds.has(u.lineId))throw Error('产品引用的产线不存在');if(u.order&&!d.orders.some(o=>o[0]===u.order))throw Error('产品引用的工单不存在')}return m}
function validateSopMetadata(groups){if(!Array.isArray(groups))throw Error('SOP 清单格式无效');let ids=new Set();for(let g of groups){if(!g||typeof g.id!=='string'||!/^[A-Za-z0-9-]+$/.test(g.id)||ids.has(g.id)||typeof g.title!=='string'||typeof g.version!=='string'||!Number.isInteger(g.process)||g.process<0||g.process>4||!Number.isInteger(g.seconds)||g.seconds<3||g.seconds>300||!['待审核','已发布','已归档'].includes(g.status)||!Array.isArray(g.files)||!g.files.length||g.files.length>20)throw Error('SOP 清单包含无效文件组');ids.add(g.id);for(let f of g.files)if(typeof f.id!=='string'||typeof f.name!=='string'||!Number.isFinite(f.size)||!['image','pdf','video'].includes(f.type))throw Error('SOP 文件索引无效')}for(let p=0;p<5;p++)if(groups.filter(g=>g.process===p&&g.status==='已发布').length>1)throw Error('同一工序存在多份已发布版本');return groups}
const shapeBeforeRelations=validateBackupShape;validateBackupShape=function(b){let d=shapeBeforeRelations(b);if(d.productionModel)validateProductionModel(d.productionModel,d);if(d.sopMetadata)validateSopMetadata(d.sopMetadata);return d};
const countsBeforeRelations=backupCounts;backupCounts=function(d){return countsBeforeRelations(d)+(d.productionModel?detailRows([['产线 / 工位',d.productionModel.lines.length+' / '+d.productionModel.stations.length]]):'')+(d.sopMetadata?detailRows([['SOP 文件组索引',d.sopMetadata.length+' 组（不含文件附件）']]):'')};
const restoreBeforeRelations=applyRestore;applyRestore=function(){let d=pendingRestore?.data,ready=auth?.role==='admin'&&d&&$('#restoreConfirm').checked;if(!ready)return restoreBeforeRelations();let snapshots=[[PLANTKEY,localStorage.getItem(PLANTKEY)],[SOPKEY,localStorage.getItem(SOPKEY)]];try{if(d.productionModel){validateProductionModel(d.productionModel,d);localStorage.setItem(PLANTKEY,JSON.stringify(d.productionModel))}if(d.sopMetadata){validateSopMetadata(d.sopMetadata);localStorage.setItem(SOPKEY,JSON.stringify(d.sopMetadata))}}catch(e){for(let [k,v] of snapshots){if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}toast('关联配置无法恢复：'+e.message);return}restoreBeforeRelations();if(pendingRestore===null){if(d.productionModel)plant=d.productionModel;if(d.sopMetadata)sopGroups=d.sopMetadata;activeStationKey='';wfCode='';autoPending=false;selectProductionOrder(orders[0]?.[0]);render()}else for(let [k,v] of snapshots){if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}};
render();

function orderKey(id){return encodeURIComponent(id).replaceAll("'",'%27')}
function orderHasHistory(id){return units.some(u=>(u.order||'MO-20261015-001')===id)||scanLogs.some(x=>x.order===id)}
orderTable=function(){return table(['工单 / 产品','生产批次','关联产线','计划 / 完成','进度','状态','计划完成','操作'],orders.map((r,i)=>{let meta=plant.orderMeta[r[0]],key=orderKey(r[0]);return [`<b>${escapeHtml(r[0])}</b><small>${escapeHtml(r[1])} · ${escapeHtml(r[2])}</small>`,escapeHtml(meta?.batch||'未分批'),escapeHtml(plant.lines.find(l=>l.id===meta?.lineId)?.name||r[3]),escapeHtml(r[4])+' / '+escapeHtml(r[5]),`<div style="min-width:85px">${Number(r[6])||0}%<div class="progress"><i style="width:${Math.min(100,Math.max(0,Number(r[6])||0))}%"></i></div></div>`,badge(r[7]),escapeHtml(r[8]),`<div class="actions">${button('详情',`orderDetail(${i})`)}${auth&&['admin','supervisor'].includes(auth.role)?button('修改',`editProductionOrder('${key}')`)+button('删除',`deleteProductionOrder('${key}')`,'danger'):''}</div>`]}))};
function editProductionOrder(key){if(!canPlantEdit())return;let id=decodeURIComponent(key),o=orders.find(o=>o[0]===id);if(!o)return;let meta=plant.orderMeta[id],locked=orderHasHistory(id);modal('修改生产工单',`<div class="formgrid"><label class="field">工单编号<input value="${escapeHtml(id)}" disabled></label><label class="field">生产批次<input id="editJobBatch" value="${escapeHtml(meta?.batch||'')}" ${locked?'disabled':''}></label><label class="field">产品名称<input id="editJobProduct" value="${escapeHtml(o[1])}" ${locked?'disabled':''}></label><label class="field">计划数量<input id="editJobPlan" type="number" min="1" value="${String(o[4]).replaceAll(',','')}"></label><label class="field">关联产线<select id="editJobLine" ${locked?'disabled':''}>${plant.lines.map(l=>`<option value="${l.id}" ${l.id===meta?.lineId?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select></label><label class="field">计划完成<input id="editJobDue" value="${escapeHtml(o[8])}" placeholder="例如 2026-10-16 18:00"></label></div><p class="hint">${locked?'工单已有生产记录，产品、批次和产线关联已锁定；可调整计划数量与交期。':'工单编号保持不变，其他信息可修改。'}</p>`,button('取消','closeModal()')+button('保存修改',`saveProductionOrderEdit('${key}')`,'primary'))}
function saveProductionOrderEdit(key){if(!canPlantEdit())return;let id=decodeURIComponent(key),o=orders.find(o=>o[0]===id);if(!o)return;let locked=orderHasHistory(id),meta=plant.orderMeta[id],plan=Number($('#editJobPlan').value),due=$('#editJobDue').value.trim();let completed=Math.max(Number(String(o[5]).replaceAll(',',''))||0,units.filter(u=>(u.order||'MO-20261015-001')===id).length);if(!Number.isInteger(plan)||plan<1||plan<completed||!due||/[<>]/.test(due)){toast('计划数量必须为正整数，且不能少于已完成 / 已投产数量 '+completed+' 台；请填写有效交期');return}let batch=locked?meta.batch:$('#editJobBatch').value.trim(),product=locked?o[1]:$('#editJobProduct').value.trim(),line=plant.lines.find(l=>l.id===(locked?meta.lineId:$('#editJobLine').value));if(!batch||!product||!line||/[<>]/.test(batch+product)){toast('请填写有效产品、批次及产线');return}o[1]=product;o[3]=line.name;o[4]=String(plan);o[6]=Math.min(100,Math.round((Number(String(o[5]).replaceAll(',',''))||0)/plan*100));o[8]=due;plant.orderMeta[id]={lineId:line.id,batch};savePlant();persistAdmin();if(wfJob.id===id)selectProductionOrder(id);adminLog('修改生产工单',id);closeModal();render();toast('生产工单已修改')}
function deleteProductionOrder(key){if(!canPlantEdit())return;let id=decodeURIComponent(key),o=orders.find(o=>o[0]===id);if(!o)return;if(orderHasHistory(id)||Number(String(o[5]).replaceAll(',',''))>0){toast('工单已有生产数量或追溯记录，不能直接删除');return}modal('删除生产工单',`<p>确认删除未产生生产记录的工单 <b>${escapeHtml(id)}</b>？</p><p class="sub">关联批次：${escapeHtml(plant.orderMeta[id]?.batch||'未分批')}</p>`,button('取消','closeModal()')+button('确认删除',`confirmProductionOrderDelete('${key}')`,'danger'))}
function confirmProductionOrderDelete(key){if(!canPlantEdit())return;let id=decodeURIComponent(key),o=orders.find(o=>o[0]===id);if(!o||orderHasHistory(id)||Number(String(o[5]).replaceAll(',',''))>0){toast('该工单已有生产数据，删除已取消');return}orders=orders.filter(o=>o[0]!==id);delete plant.orderMeta[id];if(wfJob.id===id){wfCode='';autoPending=false;if(orders.length)selectProductionOrder(orders[0][0]);else{wfJob.id='';wfJob.plan=0}}savePlant();persistAdmin();adminLog('删除生产工单',id);closeModal();render();toast('生产工单已删除')}
const lookupBeforeOrderGuard=wfLookup;wfLookup=function(){if(!orders.some(o=>o[0]===wfJob.id)){toast('请先选择有效的生产工单');return}lookupBeforeOrderGuard()};
render();
